// Heat diffusion on the GPU via WebGPU (Deno).

export interface Grid {
  width: number;
  height: number;
  steps: number;
  cells: Uint32Array;
}

export function parseInput(text: string): Grid {
  const tokens = text.split(/\s+/).filter((t) => t.length > 0);
  if (tokens.length < 3) throw new Error("input must start with <width> <height> <steps>");
  const nums = tokens.map((t, i) => {
    if (!/^\d+$/.test(t)) throw new Error(`token ${i + 1} is not a whole number: ${t}`);
    return Number(t);
  });
  const [width, height, steps] = nums;
  if (width < 1 || width > 512) throw new Error(`width out of range: ${width}`);
  if (height < 1 || height > 512) throw new Error(`height out of range: ${height}`);
  if (steps > 1000) throw new Error(`steps out of range: ${steps}`);
  const n = width * height;
  if (nums.length - 3 !== n) {
    throw new Error(`expected ${n} cells, found ${nums.length - 3}`);
  }
  const cells = new Uint32Array(n);
  for (let i = 0; i < n; i++) {
    const v = nums[i + 3];
    if (v > 1000000) throw new Error(`cell value out of range: ${v}`);
    cells[i] = v;
  }
  return { width, height, steps, cells };
}

const WG = 8;

const SHADER = /* wgsl */ `
struct Dims { width: u32, height: u32 }
@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(${WG}, ${WG})
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
  let x = id.x;
  let y = id.y;
  if (x >= dims.width || y >= dims.height) { return; }
  let w = dims.width;
  let xl = select(x - 1u, x, x == 0u);
  let xr = select(x + 1u, x, x + 1u >= w);
  let yu = select(y - 1u, y, y == 0u);
  let yd = select(y + 1u, y, y + 1u >= dims.height);
  let self_v = src[y * w + x];
  let sum = 4u * self_v + src[y * w + xl] + src[y * w + xr] + src[yu * w + x] + src[yd * w + x];
  dst[y * w + x] = sum / 8u;
}
`;

export async function diffuseGPU(grid: Grid): Promise<Uint32Array> {
  const { width, height, steps, cells } = grid;
  if (steps === 0) return cells.slice();
  const adapter = await navigator.gpu?.requestAdapter();
  if (!adapter) throw new Error("no WebGPU adapter available");
  const device = await adapter.requestDevice();
  try {
    const size = cells.byteLength;
    const usage = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST;
    const bufs = [
      device.createBuffer({ size, usage }),
      device.createBuffer({ size, usage }),
    ];
    device.queue.writeBuffer(bufs[0], 0, cells);
    const dims = device.createBuffer({
      size: 8,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(dims, 0, new Uint32Array([width, height]));
    const readback = device.createBuffer({
      size,
      usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
    });

    const module = device.createShaderModule({ code: SHADER });
    const pipeline = device.createComputePipeline({
      layout: "auto",
      compute: { module, entryPoint: "main" },
    });
    const layout = pipeline.getBindGroupLayout(0);
    const groups = [0, 1].map((i) =>
      device.createBindGroup({
        layout,
        entries: [
          { binding: 0, resource: { buffer: dims } },
          { binding: 1, resource: { buffer: bufs[i] } },
          { binding: 2, resource: { buffer: bufs[1 - i] } },
        ],
      })
    );

    const encoder = device.createCommandEncoder();
    const gx = Math.ceil(width / WG);
    const gy = Math.ceil(height / WG);
    for (let s = 0; s < steps; s++) {
      // One pass per step: every step reads only what the previous step wrote.
      const pass = encoder.beginComputePass();
      pass.setPipeline(pipeline);
      pass.setBindGroup(0, groups[s % 2]);
      pass.dispatchWorkgroups(gx, gy);
      pass.end();
    }
    encoder.copyBufferToBuffer(bufs[steps % 2], 0, readback, 0, size);
    device.queue.submit([encoder.finish()]);

    await readback.mapAsync(GPUMapMode.READ);
    const out = new Uint32Array(readback.getMappedRange().slice(0));
    readback.unmap();
    return out;
  } finally {
    device.destroy();
  }
}

export function formatOutput(width: number, height: number, cells: Uint32Array): string {
  const lines: string[] = [];
  let total = 0;
  for (let y = 0; y < height; y++) {
    const row = cells.subarray(y * width, (y + 1) * width);
    for (const v of row) total += v;
    lines.push(Array.from(row).join(" "));
  }
  lines.push(`SUM ${total}`);
  return lines.join("\n") + "\n";
}

async function main() {
  const path = Deno.args[0];
  if (!path) {
    console.error("usage: deno run --allow-read main.ts <input-file>");
    Deno.exit(2);
  }
  try {
    const grid = parseInput(await Deno.readTextFile(path));
    const result = await diffuseGPU(grid);
    const out = new TextEncoder().encode(formatOutput(grid.width, grid.height, result));
    let written = 0;
    while (written < out.length) written += await Deno.stdout.write(out.subarray(written));
  } catch (e) {
    console.error(`error: ${e instanceof Error ? e.message : e}`);
    Deno.exit(1);
  }
}

if (import.meta.main) {
  await main();
  Deno.exit(0);
}
