import { diffuseGPU, formatOutput, type Grid, parseInput } from "./main.ts";

function diffuseCPU(g: Grid): Uint32Array {
  const { width: w, height: h } = g;
  let cur = g.cells.slice();
  for (let s = 0; s < g.steps; s++) {
    const next = new Uint32Array(w * h);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const at = (xx: number, yy: number) =>
          cur[Math.min(h - 1, Math.max(0, yy)) * w + Math.min(w - 1, Math.max(0, xx))];
        next[y * w + x] = Math.floor(
          (4 * at(x, y) + at(x - 1, y) + at(x + 1, y) + at(x, y - 1) + at(x, y + 1)) / 8,
        );
      }
    }
    cur = next;
  }
  return cur;
}

function assertEq(a: Uint32Array, b: Uint32Array) {
  if (a.length !== b.length) throw new Error(`length ${a.length} != ${b.length}`);
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) throw new Error(`mismatch at ${i}: ${a[i]} != ${b[i]}`);
  }
}

Deno.test("hand-computed 3x1, 1 step", async () => {
  const g = parseInput("3 1 1\n0 8 0\n");
  // left: (0+0+8+0+0)/8=1, mid: (32+0+0+8+8)/8=6, right: 1
  const out = await diffuseGPU(g);
  if (formatOutput(3, 1, out) !== "1 6 1\nSUM 8\n") throw new Error(formatOutput(3, 1, out));
});

Deno.test("steps = 0 leaves grid unchanged", async () => {
  const g = parseInput("2 2 0\n1 2\n3 4\n");
  if (formatOutput(2, 2, await diffuseGPU(g)) !== "1 2\n3 4\nSUM 10\n") throw new Error();
});

Deno.test("1x1 grid is constant", async () => {
  const g = parseInput("1 1 1000\n1000000\n");
  assertEq(await diffuseGPU(g), new Uint32Array([1000000]));
});

Deno.test("random grids match CPU reference", async () => {
  const dims = [[1, 7], [7, 1], [5, 9], [17, 13], [64, 3], [100, 37], [512, 512]];
  for (const [w, h] of dims) {
    const steps = w * h > 10000 ? 50 : Math.floor(Math.random() * 200);
    const cells = new Uint32Array(w * h).map(() => Math.floor(Math.random() * 1000001));
    const g: Grid = { width: w, height: h, steps, cells };
    assertEq(await diffuseGPU(g), diffuseCPU(g));
  }
});

Deno.test("max grid sum exceeds 32 bits", async () => {
  const g: Grid = { width: 512, height: 512, steps: 3, cells: new Uint32Array(512 * 512).fill(1000000) };
  const out = formatOutput(512, 512, await diffuseGPU(g));
  if (!out.endsWith("SUM 262144000000\n")) throw new Error("bad sum");
});
